using ProblemDetailsDemo;

var builder = WebApplication.CreateBuilder(args);

// Register ProblemDetails services and the global exception handler
builder.Services.AddProblemDetails();
builder.Services.AddExceptionHandler<GlobalExceptionHandler>();

var app = builder.Build();

// Must come before endpoint routing so it catches all exceptions
app.UseExceptionHandler();

app.UseHttpsRedirection();

// --- Demo endpoints to exercise each error path ---

app.MapGet("/items/{id:int}", (int id) =>
{
    if (id == 0)
        throw new ArgumentException("Id must be greater than zero.");

    if (id == 999)
        throw new KeyNotFoundException($"Item with id {id} was not found.");

    if (id == 42)
        throw new InvalidOperationException("Item 42 is in a conflicting state.");

    if (id == 13)
        throw new Exception("Something unexpected happened.");

    return Results.Ok(new { Id = id, Name = $"Item-{id}" });
});

app.Run();

